/* aesthetic plot v2.16.0 — generated by scripts/build-registry.mjs. */
@import './aesthetic.base.css';

:root {
  --ae-line: #e9e9e9;
  --ae-ok: #15714b;
  --ae-warn: #8a5f32;
  --ae-err: #a84138;
  --ae-line-dark: #262626;
  --ae-ok-dark: #6fd2a8;
  --ae-warn-dark: #c49d72;
  --ae-err-dark: #e58379;
  --ae-soft: 240ms;
}

@media (prefers-color-scheme: dark) {
  :root:not(.light):not([data-ae-mode='light']) {
    --ae-line: var(--ae-line-dark);
    --ae-ok: var(--ae-ok-dark);
    --ae-warn: var(--ae-warn-dark);
    --ae-err: var(--ae-err-dark);
  }
}

.light,
[data-ae-mode='light'] {
  color-scheme: light;
}

.dark,
[data-ae-mode='dark'] {
  color-scheme: dark;
  --ae-line: var(--ae-line-dark);
  --ae-ok: var(--ae-ok-dark);
  --ae-warn: var(--ae-warn-dark);
  --ae-err: var(--ae-err-dark);
}

.ae-ok {
color: var(--ae-ok);
}

.ae-warn {
color: var(--ae-warn);
}

.ae-err {
color: var(--ae-err);
}

.ae-plot {
display: block;
  width: 100%;
  height: auto;
  font-family: var(--ae-font-mono);
}

.ae-plot-axis {
fill: none;
  stroke: var(--ae-line);
  stroke-width: 1;
}

.ae-plot-frontier {
fill: none;
  stroke: var(--ae-ink);
  stroke-width: 1.5;
  stroke-dasharray: 5 4;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.ae-plot-dot {
fill: var(--ae-ink);
  transition: fill var(--ae-soft) var(--ae-ease);
}

.ae-plot-dot.is-dominated {
fill: var(--ae-ink-faint);
}

.ae-plot-dot.is-chosen {
fill: var(--ae-accent);
}

.ae-plot-glyph {
fill: none;
  stroke: var(--ae-ink);
  stroke-width: 2;
  stroke-linecap: round;
}

.ae-plot-glyph.ae-ok {
stroke: var(--ae-ok);
}

.ae-plot-glyph.ae-warn {
stroke: var(--ae-warn);
}

.ae-plot-glyph.ae-err {
stroke: var(--ae-err);
}
